def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                c=g[i][j]; stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    a,b=stack.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==c and not seen[x][y]:
                            seen[x][y]=True; stack.append((x,y))
                out.append((c,cells))
    return out
