def f(g):
    H=len(g); W=len(g[0])
    d=[y for y in range(H) if all(x==5 for x in g[y])][0]
    top=[r[:] for r in g[:d]]; bot=[r[:] for r in g[d+1:]]
    tt=comps_of(top); tb=comps_of(bot)
    def norm(cells):
        ys=[y for y,x in cells]; xs=[x for y,x in cells]
        return frozenset((y-min(ys), x-min(xs)) for y,x in cells)
    # template = multi-cell comp in top that also appears unchanged (same color&shape) in bottom
    tmpl=None
    for c in [x for x in tt if len(x['cells'])>1]:
        n=norm(c['cells']); col=c['color']
        for b in tb:
            if b['color']==col and norm(b['cells'])==n and len(b['cells'])>1:
                tmpl=c; break
        if tmpl: break
    if tmpl is None:
        # fallback: the unique big template in bottom & its match in top by largest non-zero comp
        big=max(tb,key=lambda b:len(b['cells']))
        best=max([c for c in tt if c not in tb and c['color']==big['color']],key=lambda c:len(c['cells']))
        tmpl=best
    tcells=sorted(tmpl['cells']); ty0=min(y for y,x in tcells); tx0=min(x for y,x in tcells)
    th=max(y for y,x in tcells)-ty0+1; tw=max(x for y,x in tcells)-tx0+1
    O=[[0]*W for _ in range(len(bot))]
    for gy,gx in tcells:
        O[gy-(d+1)][gx]=g[gy][gx]
    for c in tt:
        if c is tmpl or c['color']==0 or len(c['cells'])==1: continue
        cy0=min(y for y,x in c['cells']); cx0=min(x for y,x in c['cells'])
        ch=max(y for y,x in c['cells'])-cy0+1; cw=max(x for y,x in c['cells'])-cx0+1
        oty=ty0-ch if ty0-ch>=0 else ty0+th
        ox=tx0+(tw-cw)//2
        for gy,gx in c['cells']:
            O[gy-(d+1)+oty][gx+ox]=g[gy][gx]
    return O
