# Define family of rules as tuples (srcSel, vPref, hAlign) and test combos
def build(rule):
    sel,vpref,halign = rule
    def f(A):
        H=len(A); W=len(A[0])
        di=max(j for j,r in enumerate(A) if all(x==5 for x in r))
        ti=comps4(A[:di]); bi=comps4(A[di+1:])
        tmpl=max(bi,key=lambda b:len(b[5]))
        _,y0,y1,x0,x1,ct=tmpl
        hh=y1-y0+1; ww=x1-x0+1
        cands=[]
        for b in ti:
            if b[3]>x1 or b[4]<x0: cands.append(b)
        src=sel(cands,ti,tmpl)
        if src is None: return None
        cells=src[5]; sy=min(r for r,_ in cells); sx=min(c for _,c in cells); cc=max(c for _,c in cells)
        # vertical preferences
        sides={'above':[y0-hh],'below':[y1+1]}
        prefs=sides[vpref]
        valid=[p for p in prefs if 0<=p and p+hh<=len(bi)]
        py=valid[0] if valid else (prefs[1][0] if prefs[1] else None)
        px=halign(ww,sx,(x0+x1)//2)
        out=[[0]*W for _ in range(len(bi))]
        for y,x in ct: out[y0+y][x0+x]=A[di+1+y][x]
        for y,x in cells:
            if 0<=py+y-sy<len(out) and 0<=px+x-sx<W: out[py+y-sy][px+x-sx]=src[0]
        return out
    return f

