def f(A):
    di=find_div(A)
    top=A[:di]; bot=A[di+1:]
    ph,lenb=len(bot),len(A[0])
    bc=comps_of(bot); tc=comps_of(top)
    tmpl=max(bc,key=lambda b:len(b['cells']))
    tcells=tmpl['cells']
    ty0=min(p[0] for p in tcells); ty1=max(p[0] for p in tcells)
    tx0=min(p[1] for p in tcells); tx1=max(p[1] for p in tcells)
    # source = color in top that does NOT overlap template columns
    srcs=[b for b in tc if b['color']!=tmpl['color']]
    def disjoint(b):
        return max(c for _,c in b['cells'])<tx0 or min(c for _,c in b['cells'])>tx1
    dset={b for b in srcs if disjoint(b)}
    colors=set(b['color'] for b in dset)
    candcells={}
    for b in dset:
        cells=b['cells']; candcells.setdefault(b['color'],set()).update(cells)
    pick=None; bestn=-1
    for c,s in candcells.items():
        n=len(s); cols={x for _,x in s}
        if cols.isdisjoint({t for _,t in tcells}):
            if n>bestn: bestn=n; pick=c
    sy=min(p[0] for p in candcells[pick]); sx=min(p[1] for p in candcells[pick])
    sr=max(p[0] for p in candcells[pick]); sc=max(p[1] for p in candcells[pick])
    sh=sr-sy+1; sw=sc-sx+1
    py=ty0-sh
    if py<0 or py+sh>ph: py=ty1+1
    px=tx0-sx
    out=[row[:] for row in bot]
    cc=candcells[pick]
    for r,c in cc:
        yy=r-sy+py; xx=c-sx+px
        if 0<=yy<ph and 0<=xx<lenb:
            out[yy][xx]=pick
    return out

