def norm(cells):
    sy=min(p[0] for p in cells); sx=min(p[1] for p in cells)
    return frozenset((p[0]-sy,p[1]-sx) for p in cells)

def f(g):
    d=next(i for i,row in enumerate(g) if all(x==5 for x in row))
    B=g[:d]; C=g[d+1:]
    bc=comps_of(C)
    tmpl=max(bc,key=lambda b:len(b['cells']))
    tcol=tmpl['color']
    srel=norm(tmpl['cells'])
    dec=[b for b in bc if norm(b['cells'])==srel and b['color']==tcol]
    cands=[b for b in bc if b not in dec]
    src=max(cands,key=len)
    sy=min(p[0] for p in src['cells']); sx=min(p[1] for p in src['cells'])
    ty0=min(p[0] for p in tmpl['cells']); th=max(p[0] for p in tmpl['cells'])-ty0+1
    h=len(C)
    py=ty0-th
    px=sx-(min(p[1] for p in tmpl['cells'])-min(p[1] for p in tmpl['cells']))
    if py<0 or py+th-1>=h: py=ty0+th
    out=[row[:] for row in C]
    for dy,dx in src['cells']:
        out[py+dy-sy][px+(dx-sx)]=src['color']
    return B+out

