    # all color1 cells (any connectivity) in whole grid
    return [(y,x) for y in range(len(g)) for x in range(len(g[0])) if g[y][x]==1]

def src_of(g):
    # non-1 nonzero cells, 4-connected comps
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for y in range(H):
        for x in range(W):
            if g[y][x] and g[y][x]!=1 and (y,x) not in seen:
                col=g[y][x]; st=[(y,x)]; seen.add((y,x)); cs=[]
                while st:
                    cy,cx=st.pop(); cs.append((cy,cx))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and g[ny][nx]==col:
                            seen.add((ny,nx)); st.append((ny,nx))
                out.append(dict(color=col,cells=cs))
    return out

