# Build object list per demo with pattern signatures
def objlist(g, div_row=None):
    H,W=len(g),len(g[0])
    if div_row is None:
        div_row = next(i for i,r in enumerate(g) if all(x==5 for x in r))
    panels={'top':g[:div_row],'bot':g[div_row+1:]}
    res={}
    for name,p in panels.items():
        seen=set(); objs=[]
        for r in range(len(p)):
            for c in range(W):
                v=p[r][c]
                if v==0 or (r,c) in seen: continue
                col=v; stack=[(r,c)]; seen.add((r,c)); comp=[]
                while stack:
                    q=stack.pop(); comp.append(q)
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        pp=(q[0]+dr,q[1]+dc)
                        if 0<=pp[0]<len(p) and p[pp[0]][pp[1]]==col and pp not in seen:
                            seen.add(pp); stack.append(pp)
                rr=[p0[0] for p0 in comp]; cc=[p0[1] for p0 in comp]
                pat=tuple(sorted((a-min(rr),b-min(cc)) for a,b in comp))
                objs.append(dict(comp=comp,col=col,pat=pat,h=max(rr)-min(rr)+1,w=max(cc)-min(cc)+1,
                                  r0=min(rr),c0=min(cc),orig=(min(rr),min(cc))))
        res[name]=objs
    return res
